test("I23 real date boundary, historical expired consumer and previous I22 handoff cannot authorize current supply",()=>{
  const accepted=runBoundedGate(x=>x.now="2026-09-18T08:59:59.999Z");
  expect(accepted.status,accepted.stdout+accepted.stderr).toBe(0);
  for(const now of ["2026-09-18T09:00:00Z","2026-09-18T09:00:00.001Z"]){
    const denied=runBoundedGate(x=>x.now=now);expect(denied.status).not.toBe(0);
    expect(denied.stdout+denied.stderr).toContain("head/base/expiry mismatch");
  }
  for(const expires of ["2026-09-14T09:00:00Z","2026-09-15T09:00:00Z","2026-09-17T09:00:00Z"]){
    const oldConsumer=runBoundedGate(x=>{x.fields.expires_at=expires;x.now="2026-09-17T09:00:01Z"});
    expect(oldConsumer.status).not.toBe(0);expect(oldConsumer.stdout+oldConsumer.stderr).toContain("consumer expiry mismatch");
  }
  for(const previousId of [5660965716,5671021604,5672436570,5688909231,5694821959,5711335296]){
  const oldHandoff=runBoundedGate(x=>{
    const old=x.controls.find((c:any)=>c.id===previousId);
    x.body=x.body.replace(x.fields.handoff_comment_ref,old.html_url)
      .replace(x.fields.handoff_body_sha256,createHash("sha256").update(old.body).digest("hex"));
  });
  expect(oldHandoff.status).not.toBe(0);expect(oldHandoff.stdout+oldHandoff.stderr).toContain("exact published I required");
  }
  console.log(JSON.stringify({subcase:"I23-CURRENT-DAY-BOUNDARY",last_valid:1,at_or_after_expiry_rejected:2,old_consumer_rejected:3,old_handoff_rejected:6,product_Date_now_unchanged:true}));
});

test("I9 current consumer uses full-index across abbrev7/8 and rejects abbreviated evidence",()=>{
  const hash=(value:string)=>createHash("sha256").update(value).digest("hex");
  const current=spawnSync("git",["rev-parse","HEAD"],{cwd:repoRoot,encoding:"utf8"});
  expect(current.status).toBe(0);const head=current.stdout.trim();
  const fullDigests:string[]=[];
  for(const abbrev of [7,8]){
    const full=spawnSync("git",["-c",`core.abbrev=${abbrev}`,"diff","--binary","--full-index",`${ciBase}...${head}`],
      {cwd:repoRoot,encoding:"utf8",timeout:15000,maxBuffer:16*1024*1024});
    expect(full.status,full.stderr).toBe(0);fullDigests.push(hash(full.stdout));
    const indices=[...full.stdout.matchAll(/^index ([0-9a-f]+)\.\.([0-9a-f]+)/gm)];
    expect(indices.length).toBeGreaterThan(0);expect(indices.every(m=>m[1].length===40&&m[2].length===40)).toBe(true);
    const accepted=runBoundedGate(x=>{x.gitAbbrev=abbrev;x.fields.binary_diff_sha256=hash(full.stdout)});
    expect(accepted.status,accepted.stdout+accepted.stderr).toBe(0);
    const legacy=spawnSync("git",["-c",`core.abbrev=${abbrev}`,"diff","--binary",`${ciBase}...${head}`],
      {cwd:repoRoot,encoding:"utf8",timeout:15000,maxBuffer:16*1024*1024});
    expect(legacy.status,legacy.stderr).toBe(0);expect(hash(legacy.stdout)).not.toBe(hash(full.stdout));
    const refused=runBoundedGate(x=>{x.gitAbbrev=abbrev;x.fields.binary_diff_sha256=hash(legacy.stdout)});
    expect(refused.status).not.toBe(0);expect(refused.stdout+refused.stderr).toContain("consumer binary_diff_sha256 mismatch");
  }
  expect(fullDigests[0]).toBe(fullDigests[1]);
  console.log(JSON.stringify({subcase:"I9-FULL-INDEX-CONSUMER",head,abbrev:[7,8],full_index_sha256:fullDigests[0],all_index_ids40:true,legacy_rejections:2}));
});

import { closeSync, copyFileSync, mkdirSync, mkdtempSync, openSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

const repoRoot = process.cwd();
const headSha = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
const rapidLiteWorkflowPath = ".github/workflows/shirube-rapid-lite-gates-report.yml";
const overlayFixturePaths = [
  ".shirube/repo-spec.yaml",
  ".shirube/execution-context.yaml",
  ".shirube/adoption-intake.yaml",
  ".shirube/existing-state-scan.yaml",
  ".shirube/control-handoffs/CH-001.yaml",
  ".shirube/lifecycle-state.yaml",
  ".shirube/enforcement-policy.yaml",
  ".shirube/control-state-completeness.yaml",
  ".shirube/source-mirrors/control-issue.yaml",
  "docs/shirube/README.md",
  rapidLiteWorkflowPath,
  ".github/pull_request_template.md",
  ".github/workflows/pr-checks.yml",
  "scripts/shirube-current-overlay-check.mjs",
  // The gate imports its conformance decision from here rather than keeping a second
  // copy of the rule. An isolated gate root therefore has to carry it too.
  "scripts/lib/cell-conformance.mjs",
  ".shirube/cell-conformance.json",
];

function runGate(
  body: string,
  changedFiles: string[],
  options: {
    draft?: boolean;
    labels?: string[];
    ownerMergeMethod?: string;
    trailingCommentBody?: string;
    expectedHeadSha?: string;
    requiredMergeMethod?: string;
    eventHeadSha?: string;
    workflowBody?: string;
    cliArgs?: string[];
    ownerHeadSha?: string;
    ownerDecisions?: Array<{
      mergeMethod: string;
      supersedesDecisionRef?: string;
    }>;
  } = {},
) {
  const dir = mkdtempSync(join(tmpdir(), "shirube-current-overlay-"));
  const eventPath = join(dir, "event.json");
  const changedFilesPath = join(dir, "changed-files.txt");

  const draft = options.draft ?? true;
  const labels = options.labels ?? [];
  const eventHeadSha = options.eventHeadSha ?? headSha;
  writeFileSync(eventPath, JSON.stringify({
    number: 999,
    pull_request: {
      number: 999,
      draft,
      body,
      labels: labels.map((name) => ({ name })),
      head: { sha: eventHeadSha },
    },
  }));
  writeFileSync(changedFilesPath, `${changedFiles.join("\n")}\n`);
  const commentsPath = join(dir, "comments.json");
  const ownerDecisions = options.ownerDecisions ?? [{ mergeMethod: options.ownerMergeMethod ?? "merge" }];
  const comments = ownerDecisions.map((decision, index) => {
    const decisionUrl = `https://github.com/watchout/agent-comms-mcp/pull/999#issuecomment-${index + 1}`;
    return {
      body: [
        "shirube_owner_decision:",
        "  schema_version: shirube-owner-decision/v1",
        "  target_repo: watchout/agent-comms-mcp",
        "  target_pr: 999",
        `  exact_head_sha: ${options.ownerHeadSha ?? eventHeadSha}`,
        "  verdict: APPROVED_EXACT_HEAD",
        `  merge_method: ${decision.mergeMethod}`,
        decision.supersedesDecisionRef
          ? `  supersedes_decision_ref: ${decision.supersedesDecisionRef}`
          : "",
        "  actor: watchout",
        `  decision_ref: ${decisionUrl}`,
        index === ownerDecisions.length - 1 ? options.trailingCommentBody ?? "" : "",
      ].filter(Boolean).join("\n"),
      user: { login: "watchout" },
      author_association: "OWNER",
      html_url: decisionUrl,
    };
  });
  writeFileSync(commentsPath, JSON.stringify(comments));

  let gateRoot = repoRoot;
  if (options.workflowBody !== undefined) {
    gateRoot = join(dir, "repo");
    for (const relativePath of overlayFixturePaths) {
      const destination = join(gateRoot, relativePath);
      mkdirSync(dirname(destination), { recursive: true });
      copyFileSync(join(repoRoot, relativePath), destination);
    }
    writeFileSync(join(gateRoot, rapidLiteWorkflowPath), options.workflowBody);
  }

  try {
    return spawnSync("node", [
      "scripts/shirube-current-overlay-check.mjs",
      "--repo",
      "watchout/agent-comms-mcp",
      "--event",
      eventPath,
      "--changed-files",
      changedFilesPath,
      "--comments",
      commentsPath,
      ...(options.expectedHeadSha ? ["--expected-head", options.expectedHeadSha] : []),
      ...(options.requiredMergeMethod ? ["--required-merge-method", options.requiredMergeMethod] : []),
      ...(options.cliArgs ?? []),
    ], {
      cwd: gateRoot,
      encoding: "utf8",
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function baseBody(cellId: string, riskTier: string) {
  return [
    "## Shirube Metadata",
    `CELL-ID: ${cellId}`,
    `Risk Tier: ${riskTier}`,
    `Exact Head SHA: ${headSha}`,
    "",
    "## Allowed paths",
    "- bin/**",
    "- core/**",
    "- tests/**",
    "",
    "## Protected surfaces",
    "```text",
    "touched: runtime read-only planning surface",
    "declared: runtime",
    "```",
    "",
    "## Validation",
    "- pending",
  ].join("\n");
}

describe("shirube-current-overlay-check", () => {
  test("allows runtime implementation PRs under the installed overlay gate", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      [
        "bin/aun/runtime-v2.ts",
        "core/aun-runtime-v2-claim-plan.ts",
        "tests/aun-runtime-v2-claim-plan.test.ts",
      ],
    );

    expect(result.status).toBe(0);
    expect(result.stdout).toContain("Shirube current-overlay gate passed.");
  });

  test("still blocks runtime files in the Rapid/Lite adoption overlay PR", () => {
    const result = runGate(
      baseBody("CELL-MCP-SHIRUBE-RAPID-LITE-PILOT-001", "R2"),
      [
        ".shirube/repo-spec.yaml",
        "core/aun-runtime-v2-claim-plan.ts",
      ],
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("core/aun-runtime-v2-claim-plan.ts is a runtime/product protected file");
  });

  test("allows a non-draft PR when the owner decision and one merge-method label match", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"],
        ownerMergeMethod: "merge",
      },
    );

    expect(result.status).toBe(0);
    expect(result.stdout).toContain("Shirube current-overlay gate passed.");
  });

  test("blocks a merge-method label that disagrees with the exact-head owner decision", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:squash"],
        ownerMergeMethod: "merge",
      },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("Owner decision merge_method=merge does not match label merge-method:squash.");
  });

  test("blocks an owner decision that omits merge_method", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"],
        ownerMergeMethod: "",
      },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("Owner decision must select merge_method=merge, squash, or rebase; got <empty>.");
  });

  test("blocks missing, multiple, and unsupported merge-method labels", () => {
    for (const labels of [
      ["owner-exact-head-approved", "shirube-current-overlay"],
      ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge", "merge-method:squash"],
      ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:octopus"],
    ]) {
      const result = runGate(
        baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
        ["tests/aun-runtime-v2-claim-plan.test.ts"],
        { draft: false, labels, ownerMergeMethod: "merge" },
      );
      expect(result.status).toBe(1);
    }
  });

  test("parses merge_method only from the shirube owner decision block", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"],
        ownerMergeMethod: "merge",
        trailingCommentBody: "next_action:\n  merge_method: squash",
      },
    );

    expect(result.status).toBe(0);
  });

  test("fails closed when exact-head owner decisions conflict without explicit supersession", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:squash"],
        ownerDecisions: [{ mergeMethod: "squash" }, { mergeMethod: "merge" }],
      },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("requires exactly one authoritative owner decision after explicit supersession; found 2");
  });

  test("accepts one current exact-head decision when it explicitly supersedes the prior decision", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"],
        ownerDecisions: [
          { mergeMethod: "squash" },
          {
            mergeMethod: "merge",
            supersedesDecisionRef: "https://github.com/watchout/agent-comms-mcp/pull/999#issuecomment-1",
          },
        ],
      },
    );

    expect(result.status).toBe(0);
  });

  test("fails closed when a superseding decision changes method but the live label is stale", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:squash"],
        ownerDecisions: [
          { mergeMethod: "squash" },
          {
            mergeMethod: "merge",
            supersedesDecisionRef: "https://github.com/watchout/agent-comms-mcp/pull/999#issuecomment-1",
          },
        ],
      },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("Owner decision merge_method=merge does not match label merge-method:squash.");
  });

  test("fails closed when supersedes_decision_ref does not identify a prior valid exact-head decision", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"],
        ownerDecisions: [{
          mergeMethod: "merge",
          supersedesDecisionRef: "https://github.com/watchout/agent-comms-mcp/pull/999#issuecomment-404",
        }],
      },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("has invalid supersedes_decision_ref=");
  });

  test("fails closed when the live PR head differs from the checked workflow head", () => {
    const checkedHead = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"],
        ownerMergeMethod: "merge",
        expectedHeadSha: checkedHead,
      },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain(`Live PR head ${headSha} does not match checked head ${checkedHead}.`);
  });

  test("allows auto-squash revalidation only while the live decision and label remain squash", () => {
    const result = runGate(
      baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
      ["tests/aun-runtime-v2-claim-plan.test.ts"],
      {
        draft: false,
        labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:squash"],
        ownerMergeMethod: "squash",
        expectedHeadSha: headSha,
        requiredMergeMethod: "squash",
      },
    );

    expect(result.status).toBe(0);
  });

  test.each(["merge", "rebase"])(
    "fails a stale auto-squash run after the live authority changes to %s",
    (currentMethod) => {
      const result = runGate(
        baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"),
        ["tests/aun-runtime-v2-claim-plan.test.ts"],
        {
          draft: false,
          labels: ["owner-exact-head-approved", "shirube-current-overlay", `merge-method:${currentMethod}`],
          ownerDecisions: [
            { mergeMethod: "squash" },
            {
              mergeMethod: currentMethod,
              supersedesDecisionRef: "https://github.com/watchout/agent-comms-mcp/pull/999#issuecomment-1",
            },
          ],
          expectedHeadSha: headSha,
          requiredMergeMethod: "squash",
        },
      );

      expect(result.status).toBe(1);
      expect(result.stdout).toContain(`Execution requires merge_method=squash, but the live label selects ${currentMethod}.`);
      expect(result.stdout).toContain(`Execution requires merge_method=squash, but the authoritative owner decision selects ${currentMethod}.`);
    },
  );

  test("accepts the public same-repository exact-ref manifest-verified local runtime topology", () => {
    const workflowBody = readFileSync(join(repoRoot, rapidLiteWorkflowPath), "utf8");
    const result = runGate(
      baseBody("CELL-MCP-SHIRUBE-RAPID-LITE-PILOT-001", "R3"),
      [rapidLiteWorkflowPath],
      { workflowBody },
    );

    expect(result.status).toBe(0);
    expect(result.stdout).toContain("Shirube current-overlay gate passed.");
  });

  test("rejects a private ADF reusable workflow call or checkout", () => {
    const canonical = readFileSync(join(repoRoot, rapidLiteWorkflowPath), "utf8");
    const privateRef = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    const variants = [
      canonical.replace(
        "jobs:\n",
        `jobs:\n  forbidden-private-call:\n    uses: \"watchout/ai-dev-framework/.github/workflows/shirube-rapid-lite-reusable.yml@${privateRef}\"\n`,
      ),
      canonical.replace(
        "repository: watchout/agent-comms-mcp",
        "repository: watchout/ai-dev-framework",
      ),
    ];

    for (const workflowBody of variants) {
      const result = runGate(
        baseBody("CELL-MCP-SHIRUBE-RAPID-LITE-PILOT-001", "R3"),
        [rapidLiteWorkflowPath],
        { workflowBody },
      );
      expect(result.status).toBe(1);
      expect(result.stdout).toContain("must not call or checkout the private ADF repository");
    }
  });

  test("rejects a drifted public runtime ref", () => {
    const canonical = readFileSync(join(repoRoot, rapidLiteWorkflowPath), "utf8");
    const workflowBody = canonical.replace(
      "4ea4b8bc122e22c47323fc8836dc3d7aedd487e9",
      "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
    );
    const result = runGate(
      baseBody("CELL-MCP-SHIRUBE-RAPID-LITE-PILOT-001", "R3"),
      [rapidLiteWorkflowPath],
      { workflowBody },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("must declare the exact pinned public runtime ref once");
  });

  test("rejects missing strict runtime manifest verification", () => {
    const canonical = readFileSync(join(repoRoot, rapidLiteWorkflowPath), "utf8");
    const workflowBody = canonical.replace("sha256sum --check --strict", "sha256sum --check");
    const result = runGate(
      baseBody("CELL-MCP-SHIRUBE-RAPID-LITE-PILOT-001", "R3"),
      [rapidLiteWorkflowPath],
      { workflowBody },
    );

    expect(result.status).toBe(1);
    expect(result.stdout).toContain("must include sha256sum --check --strict");
  });
});

test("C207 source-specific original JSON and actual marked OD syntax",()=>{
  const source=readFileSync(join(repoRoot,"scripts/shirube-current-overlay-check.mjs"),"utf8");
  const begin=source.indexOf("function requireCiOwnerDecision("),end=source.indexOf("\nasync function boundedGithubGet",begin);
  expect(begin).toBeGreaterThan(-1);expect(end).toBeGreaterThan(begin);
  expect(source.indexOf("function requireCiOwnerDecision(",begin+1)).toBe(-1);
  const parse=new Function(source.slice(begin,end)+";return requireCiOwnerDecision")();
  const original=ciAuthorityFixtures[0].body,id="OD-CTO-963-NARROW-CI-UNBLOCK-20260909-001";
  expect(parse(original,id,false).decision_id).toBe(id);
  for(const [index,expected] of [[2,"OD-CTO-963-C2-TEST-SCOPE-AND-BINDING-20260910-001"],[3,"OD-CTO-APPROVAL-NORMALIZATION-20260910-001"]] as const)
    expect(parse(ciAuthorityFixtures[index].body,expected,true).decision_id).toBe(expected);
  const block=original.match(/^```json\s*\n([\s\S]*?)^```\s*$/m)![0];
  const cases=[
    original.replace(id,"wrong"),original.replace(/"decision_id": "[^"]*",/,""),
    original.replace('"decision_id":','"decision_id":"duplicate","decision_id":'),
    original+"\n"+block,original.replace('"decision_id":','"decision_id" INVALID:'),
    "<!-- shirube-v3:owner-decision:"+id+" -->\n"+original,
    original.replace('"decision": "APPROVED"','"decision": "PENDING"'),
    original.replace('"owner": "watchout"','"owner": "maker"'),
    original.replace('"schema_version": "shirube-owner-decision/v1"','"schema_version": "other"'),
    original.replace('"control_source": "watchout/agent-comms-mcp#940"','"control_source": "other"'),
  ];
  for(const bad of cases)expect(()=>parse(bad,id,false)).toThrow("owner decision source form mismatch");
  const marked=ciAuthorityFixtures[2].body,mid="OD-CTO-963-C2-TEST-SCOPE-AND-BINDING-20260910-001";
  for(const bad of [marked.replace(/<!--[^>]*-->/,""),marked+"\n"+marked.match(/<!--[^>]*-->/)![0],marked.replace(mid,"wrong")])
    expect(()=>parse(bad,mid,true)).toThrow();
  console.log(JSON.stringify({subcase:"C207-source-forms",positive:3,negative:cases.length+3,authenticated_overlay_positive_separate:true}));
});

test("I6 actual workflow collector preserves a repository binary diff above 1 MiB and refuses incomplete subjects",()=>{
  const workflow=readFileSync(join(repoRoot,".github/workflows/pr-checks.yml"),"utf8");
  const match=/^          node --input-type=module > bounded-ci-subject\.json <<'JS'\n([\s\S]*?)^          JS$/m.exec(workflow);
  expect(match).not.toBeNull();
  const collector=match![1].split("\n").map(line=>line.startsWith("          ")?line.slice(10):line).join("\n");
  const dir=mkdtempSync(join(tmpdir(),"bounded-ci-actual-subject-"));
  try{
    const git=(...args:string[])=>{
      const r=spawnSync("git",args,{cwd:repoRoot,encoding:"utf8",timeout:15000,maxBuffer:16*1024*1024});
      expect(r.status,r.stderr).toBe(0);return r.stdout.trim();
    };
    const head=git("rev-parse","HEAD"),tree=git("rev-parse","HEAD^{tree}");
    const diffFile=join(dir,"independent.diff"),fd=openSync(diffFile,"w");
    let diffResult;
    try{diffResult=spawnSync("git",["diff","--binary","--full-index",`${ciBase}...${head}`],{cwd:repoRoot,stdio:["ignore",fd,"pipe"],timeout:15000});}
    finally{closeSync(fd)}
    expect(diffResult!.status,diffResult!.stderr?.toString()).toBe(0);
    const bytes=readFileSync(diffFile);expect(bytes.length).toBeGreaterThan(1024*1024);
    const hash=(value:Buffer|string)=>createHash("sha256").update(value).digest("hex");
    const event=join(dir,"event.json");writeFileSync(event,JSON.stringify({pull_request:{head:{sha:head},base:{sha:ciBase}}}));
    const run=(abbrev?:number)=>spawnSync("node",["--input-type=module","-e",collector],{cwd:repoRoot,encoding:"utf8",timeout:30000,maxBuffer:16*1024*1024,
      env:{...process.env,GITHUB_EVENT_PATH:event,GITHUB_RUN_ID:"owned-collector",GITHUB_RUN_ATTEMPT:"1",...(abbrev?{GIT_CONFIG_COUNT:"1",GIT_CONFIG_KEY_0:"core.abbrev",GIT_CONFIG_VALUE_0:String(abbrev)}:{})}});
    const result=run();expect(result.status,result.stdout+result.stderr).toBe(0);
    const subject=JSON.parse(result.stdout);
    expect(subject).toEqual({base:ciBase,candidate_head:head,candidate_tree:tree,tested_commit:head,tested_tree:tree,
      tested_parents:git("rev-list","--parents","-n1","HEAD").split(" ").slice(1),binary_diff_sha256:hash(bytes),
      test_files_sha256:Object.fromEntries(["admission","admission_postgres","retry","use_trace"].map(name=>{
        const path=`tests/contract/test_queue_bounded_${name}.test.ts`;return[path,hash(readFileSync(join(repoRoot,path)))];})),
      design_raw_sha256:"ed86b14f35b97d8483bf8052dd73765732c4568a945cb6e59bc6b8b7e99ea703",
      design_canonical_sha256:"880b99e5514f9791968ba8971e9d526b59173732986c12a54e8db04413f1972e",
      run_id:"owned-collector",run_attempt:"1",scope:"TESTED_CHECKOUT_OBSERVATION",private_status:"PRIVATE_STAGE_REQUIRED"});
    for(const abbrev of [7,8]){
      const alternate=run(abbrev);expect(alternate.status,alternate.stdout+alternate.stderr).toBe(0);
      expect(JSON.parse(alternate.stdout)).toEqual(subject);
    }
    const indices=[...bytes.toString().matchAll(/^index ([0-9a-f]+)\.\.([0-9a-f]+)/gm)];
    expect(indices.length).toBeGreaterThan(0);expect(indices.every(m=>m[1].length===40&&m[2].length===40)).toBe(true);
    writeFileSync(event,JSON.stringify({pull_request:{head:{sha:head},base:{sha:"f".repeat(40)}}}));
    const refused=run();expect(refused.status).not.toBe(0);expect(refused.stdout).toBe("");
    console.log(JSON.stringify({subcase:"I6-ACTUAL-CI-COLLECTOR",binary_diff_bytes:bytes.length,binary_diff_sha256:hash(bytes),
      workflow_collector_sha256:hash(collector),head,tree,independent_file_hash_equal:true,git_failure_refused_without_subject:true,abbrev7_8_same_subject:true,all_index_ids40:true}));
  }finally{rmSync(dir,{recursive:true,force:true})}
},30000);


describe("CI-01 source admission before protected release", () => {
  const sourceReady = (x: any) => {
    x.draft = false;
    x.labels = ["shirube-current-overlay"];
    x.body = x.body.replace(headSha, x.head);
    x.cliArgs = ["--mode", "source-admission"];
  };

  test("valid bounded source reaches quality validation without release owner or merge selection", () => {
    const result = runBoundedGate(sourceReady);
    expect(result.status, result.stdout + result.stderr).toBe(0);
    expect(result.stdout).toContain('"source_admission":"CI_TEST_SUPPLY_ONLY"');
    expect(result.stdout).toContain("release authority NOT_EVALUATED");
    expect(result.stdout).not.toContain("Shirube current-overlay gate passed.");
    for (const cliArgs of [[], ["--mode", "full"]]) {
      const full = runBoundedGate(x => { sourceReady(x); x.cliArgs = cliArgs; });
      expect(full.status, full.stdout + full.stderr).toBe(1);
      expect(full.stdout).toContain("machine-verifiable shirube_owner_decision");
      expect(full.stdout).toContain("require label owner-exact-head-approved");
    }
  });

  test("existing standing-authorized ordinary route passes both modes without owner or overlay label", () => {
    const body = baseBody("CELL-AUN-602-ORDINARY-DOCS", "R0")
      + "\nOD-AUN-602-STANDING-MERGE-AND-NO-DRIFT-20260816-001"
      + "\nhttps://github.com/watchout/agent-comms-mcp/issues/602#issuecomment-5306783646";
    for (const cliArgs of [[], ["--mode", "full"], ["--mode", "source-admission"]]) {
      const result = runGate(body, ["docs/ordinary.md"], {
        draft: false, labels: ["merge-method:squash"], ownerDecisions: [], cliArgs,
      });
      expect(result.status, result.stdout + result.stderr).toBe(0);
      if (cliArgs.includes("source-admission")) expect(result.stdout).toContain("release authority NOT_EVALUATED");
      else expect(result.stdout).toContain("Exact-head owner decision waived under OD-AUN-602-STANDING-MERGE-AND-NO-DRIFT-20260816-001");
    }
  });

  test("the same standing waiver still refuses protected, uncited and breaking routes without overlay", () => {
    const ordinary = baseBody("CELL-AUN-602-ORDINARY-DOCS", "R0");
    const cited = ordinary + "\nOD-AUN-602-STANDING-MERGE-AND-NO-DRIFT-20260816-001"
      + "\nhttps://github.com/watchout/agent-comms-mcp/issues/602#issuecomment-5306783646";
    for (const [body, files, labels] of [
      [cited, ["config/protected.json"], ["merge-method:squash"]],
      [ordinary, ["docs/ordinary.md"], ["merge-method:squash"]],
      [cited, ["docs/ordinary.md"], ["merge-method:squash", "breaking-change-verified"]],
    ] as Array<[string, string[], string[]]>) {
      for (const cliArgs of [[], ["--mode", "source-admission"]]) {
        const result = runGate(body, files, {draft: false, labels, ownerDecisions: [], cliArgs});
        expect(result.status, result.stdout + result.stderr).toBe(1);
        expect(result.stdout).toContain("Non-draft PRs require label shirube-current-overlay.");
      }
    }
  });

  test("source mode retains expired, invalid, ambiguous source and current-overlay checks", () => {
    const cases: Array<[string, (x: any) => void, string]> = [
      ["expired source", x => x.now = "2026-09-18T09:00:00Z", "head/base/expiry mismatch"],
      ["expired consumer", x => x.fields.expires_at = "2026-09-15T09:00:00Z", "consumer expiry mismatch"],
      ["raw source drift", x => x.controls.find((c: any) => c.id === 5712041088).body += "changed", "control raw body digest mismatch"],
      ["duplicate consumer", x => x.copies = 2, "exactly one current-head consumer receipt required"],
      ["missing overlay", x => x.labels = [], "require label shirube-current-overlay"],
      ["misleading release claim", x => x.body += "\nmerge-ready", "must not claim merge-ready"],
      ["stale body", x => x.body = x.body.replace(x.head, headSha), "must include the current exact head SHA"],
      ["wrong tree", x => x.fields.candidate_tree = "f".repeat(40), "consumer candidate_tree mismatch"],
      ["maker as checker", x => x.fields.checker_agent = x.fields.maker_agent, "consumer checker_agent mismatch"],
      ["wrong source scope", x => x.files.push("config/unadmitted.json"), "candidate path outside supply"],
    ];
    for (const [name, mutate, error] of cases) {
      const result = runBoundedGate(x => { sourceReady(x); mutate(x); });
      expect(result.status, name + "\n" + result.stdout + result.stderr).toBe(1);
      expect(result.stdout, name).toContain(error);
    }
  });

  test("full mode still refuses a wrong exact-head owner and accepts the matching owner", () => {
    const body = baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1");
    const options = {draft: false, labels: ["owner-exact-head-approved", "shirube-current-overlay", "merge-method:merge"]};
    for (const cliArgs of [[], ["--mode", "full"]]) {
      const wrong = runGate(body, ["tests/aun-runtime-v2-claim-plan.test.ts"], {...options, cliArgs, ownerHeadSha: "b".repeat(40)});
      expect(wrong.status).toBe(1);
      expect(wrong.stdout).toContain("machine-verifiable shirube_owner_decision");
      const right = runGate(body, ["tests/aun-runtime-v2-claim-plan.test.ts"], {...options, cliArgs});
      expect(right.status, right.stdout + right.stderr).toBe(0);
    }
  });

  test("unknown, duplicate, missing, ambiguous and release-incompatible flags fail closed", () => {
    for (const cliArgs of [
      ["--mode"], ["--mode", ""], ["--mode", "source"], ["--mode", " source-admission"],
      ["--mode=source-admission"], ["--source-admission"], ["unparsed"],
      ["--mode", "source-admission", "--mode", "full"],
      ["--mode", "source-admission", "--mode", "source-admission"],
      ["--mode", "source-admission", "--required-merge-method", "squash"],
      ["--repo", "watchout/agent-comms-mcp"],
    ]) {
      const result = runGate(baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"), [], {cliArgs});
      expect(result.status, JSON.stringify(cliArgs)).not.toBe(0);
      expect(result.stdout + result.stderr).toContain("Invalid gate arguments");
    }
  });

  test("source-only checked-head pin remains enforced", () => {
    const result = runGate(baseBody("CELL-MCP-AUN-RUNTIME-V2-CLAIM-DRYRUN-001", "R1"), [], {
      cliArgs: ["--mode", "source-admission"], expectedHeadSha: "b".repeat(40),
    });
    expect(result.status).toBe(1);
    expect(result.stdout).toContain("does not match checked head");
  });

  test("workflow keeps fatal source before quality, full after quality, and unchanged auto-merge", () => {
    const workflow = readFileSync(join(repoRoot, ".github/workflows/pr-checks.yml"), "utf8");
    const step = (name: string) => {
      const start = workflow.indexOf("      - name: " + name + "\n");
      expect(start, name).toBeGreaterThan(0);
      const next = workflow.indexOf("      - name:", start + 1);
      return {start, text: workflow.slice(start, next < 0 ? undefined : next)};
    };
    const source = step("Shirube source-admission gate"), full = step("Shirube current-overlay gate");
    expect(source.start).toBeLessThan(step("Prepare pinned native Wasurezu fixture").start);
    expect(source.start).toBeLessThan(step("Run full test suite").start);
    expect(full.start).toBeGreaterThan(step("Verify bounded public stage (private stage remains required)").start);
    expect(source.text).toContain("--mode source-admission");
    expect(full.text).not.toContain("--mode");
    for (const gate of [source, full]) {
      expect(gate.text).toContain("if: github.event_name == 'pull_request'");
      expect(gate.text).not.toMatch(/continue-on-error|\|\| true|always\(\)/);
    }
    const baseline = spawnSync("git", ["show", ciFixtureHead + ":.github/workflows/pr-checks.yml"], {cwd: repoRoot, encoding: "utf8"});
    expect(baseline.status).toBe(0);
    const auto = (text: string) => text.slice(text.indexOf("  auto-merge:\n"));
    expect(auto(workflow)).toBe(auto(baseline.stdout));
    expect(auto(workflow)).toContain("needs.layer0.result == 'success'");
    expect(auto(workflow)).toContain("--required-merge-method squash");
    // Removing only the inserted source step and moving the original full gate
    // back must reproduce every baseline workflow byte (events, permissions,
    // commands, counts, runner and downstream protected checks included).
    let restored = workflow.replace(source.text, "").replace(full.text, "");
    restored = restored.replace("      - name: Prepare pinned native Wasurezu fixture\n", full.text + "      - name: Prepare pinned native Wasurezu fixture\n");
    expect(restored).toBe(baseline.stdout);
  });

  test("CI-01 workflow delta cannot reuse previous I21 admission", () => {
    const historical = ciAuthorityFixtures.find(x => x.id === 5694821959)!;
    const handoff = JSON.parse(/```json\s*\n([\s\S]*?)^```/m.exec(historical.body)![1]);
    expect(handoff.implementation_paths).not.toContain(".github/workflows/pr-checks.yml");
    const actual = spawnSync("git", ["rev-parse", "HEAD"], {cwd: repoRoot, encoding: "utf8"});
    expect(actual.status).toBe(0);
    if (actual.stdout.trim() !== ciFixtureHead) {
      const refused = runBoundedGate(x => {
        sourceReady(x);
        x.body = x.body.replace(x.fields.handoff_comment_ref, historical.html_url)
          .replace(x.fields.handoff_body_sha256, createHash("sha256").update(historical.body).digest("hex"));
      });
      expect(refused.status, refused.stdout + refused.stderr).toBe(1);
      expect(refused.stdout).toContain("exact published I required");
    }
  });
});
